import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, recordPayment, invoiceTotals } from '../src/invoices.js';
import { statement } from '../src/statements.js';
import { balanceDue } from '../src/invoices.js';

test('statement returns empty list for no invoices', () => {
  const result = statement('C-002', [], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-002');
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement rejects unknown customer', () => {
  const result = statement('C-999', [], '2026-10-07');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('statement rejects invalid asOf date', () => {
  const result = statement('C-002', [], '2026-13-01');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});

test('statement excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const result = statement('C-002', [inv.value], '2026-10-07');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes issued invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued.value.number);
});

test('statement includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const partial = recordPayment(issued.value, { amount: Math.floor(totals.total / 2), date: '2026-10-08' });
  const result = statement('C-002', [partial.value], '2026-10-07');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued.value.number);
});

test('statement excludes fully paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const result = statement('C-002', [paid.value], '2026-10-07');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement respects asOf date cutoff', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = statement('C-002', [issued1.value, issued2.value], '2026-10-07');

  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-05');
});

test('statement includes invoices on asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes invoices after asOf date', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.value.invoices.length, 0);
});

test('statement sorts invoices by issueDate', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);
  const issued3 = issueInvoice(inv3.value, ['INV-001', 'INV-002']);

  const result = statement('C-002', [issued1.value, issued2.value, issued3.value], '2026-10-10');

  assert.equal(result.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-07');
  assert.equal(result.value.invoices[2].issueDate, '2026-10-10');
});

test('statement includes invoice metadata', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(inv.value, []);
  const result = statement('C-002', [issued.value], '2026-10-07');

  const statementInv = result.value.invoices[0];
  assert('number' in statementInv);
  assert('issueDate' in statementInv);
  assert('dueDate' in statementInv);
  assert('total' in statementInv);
  assert('due' in statementInv);
});

test('statement includes correct total', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.value.invoices[0].total, totals.total);
});

test('statement includes correct due amount (no payment)', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const due = balanceDue(issued.value);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.value.invoices[0].due, due);
});

test('statement includes correct due amount (with partial payment)', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const half = Math.floor(totals.total / 2);
  const partial = recordPayment(issued.value, { amount: half, date: '2026-10-08' });
  const due = balanceDue(partial.value);
  const result = statement('C-002', [partial.value], '2026-10-07');

  assert.equal(result.value.invoices[0].due, due);
});

test('statement calculates totalDue correctly', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = statement('C-002', [issued1.value, issued2.value], '2026-10-07');

  const expected = balanceDue(issued1.value) + balanceDue(issued2.value);
  assert.equal(result.value.totalDue, expected);
});

test('statement filters by customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = statement('C-002', [issued1.value, issued2.value], '2026-10-07');

  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued2.value.number);
});

test('statement with vouchers', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.value.invoices[0].total, totals.total);
});

test('statement with discounts and VAT', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.value.invoices[0].total, totals.total);
});

test('statement with multiple customers', () => {
  const invoices = [];

  for (let i = 1; i <= 4; i++) {
    const inv = createInvoice({
      customerId: `C-${String(i).padStart(3, '0')}`,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    invoices.push(issueInvoice(inv.value, []).value);
  }

  const result1 = statement('C-001', invoices, '2026-10-07');
  const result2 = statement('C-002', invoices, '2026-10-07');

  assert.equal(result1.value.invoices.length, 1);
  assert.equal(result2.value.invoices.length, 1);
  assert.equal(result1.value.invoices[0].number, invoices[0].number);
  assert.equal(result2.value.invoices[0].number, invoices[1].number);
});

test('statement with mixed invoice statuses', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-06',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);
  const issued3 = issueInvoice(inv3.value, ['INV-001', 'INV-002']);

  const totals2 = invoiceTotals(issued2.value);
  const partial2 = recordPayment(issued2.value, { amount: Math.floor(totals2.total / 2), date: '2026-10-08' });

  const totals3 = invoiceTotals(issued3.value);
  const paid3 = recordPayment(issued3.value, { amount: totals3.total, date: '2026-10-08' });

  const result = statement('C-002', [issued1.value, partial2.value, paid3.value], '2026-10-07');

  // Should include issued and partially_paid, exclude paid
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-06');
});

test('statement with dueDate in response', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(inv.value, []);
  const result = statement('C-002', [issued.value], '2026-10-07');

  assert.equal(result.value.invoices[0].dueDate, '2026-11-06');
});

test('statement with large number of invoices', () => {
  const invoices = [];
  for (let i = 0; i < 50; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-${String((i % 12) + 1).padStart(2, '0')}-${String((i % 28) + 1).padStart(2, '0')}`,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    invoices.push(issueInvoice(inv.value, []).value);
  }

  const result = statement('C-002', invoices, '2026-12-31');

  assert(result.value.invoices.length > 0);
  // Verify sorted
  for (let i = 1; i < result.value.invoices.length; i++) {
    assert(result.value.invoices[i - 1].issueDate <= result.value.invoices[i].issueDate);
  }
});

